import logging
import tenacity
from tenacity import _utils, before_log, after_log, before_sleep_log, Retrying, stop_after_attempt

class L:
    def __init__(self):
        self.calls = []
    def log(self, level, msg, *args, **kwargs):
        self.calls.append((level, msg))

def test_protocol_logger():
    assert hasattr(_utils, 'LoggerProtocol')
    l = L()
    n = {'c': 0}
    def f():
        n['c'] += 1
        if n['c'] < 2:
            raise ValueError()
        return 1
    r = Retrying(stop=stop_after_attempt(3), wait=tenacity.wait_none(), before=before_log(l, logging.INFO), after=after_log(l, logging.INFO), before_sleep=before_sleep_log(l, logging.INFO))
    assert r(f) == 1
    assert len(l.calls) >= 4

import logging
import tenacity
from tenacity import _utils, before_log, after_log, before_sleep_log, before_sleep_nothing, before_nothing, after_nothing


class Rec:
    def __init__(self):
        self.calls = []

    def log(self, level, msg, /, *args, **kwargs):
        self.calls.append((level, msg, args, kwargs))


def test_custom_logger_works():
    assert hasattr(_utils, 'LoggerProtocol')
    assert _utils.find_ordinal(1) == 'first'
    r = Rec()

    @tenacity.retry(stop=tenacity.stop_after_attempt(3), wait=tenacity.wait_none(), before=before_log(r, logging.INFO), after=after_log(r, logging.INFO), before_sleep=before_sleep_log(r, logging.INFO), reraise=True)
    def f():
        raise ValueError('x')

    try:
        f()
    except ValueError:
        pass
    assert len(r.calls) >= 7
    lg = logging.getLogger('x')
    before_log(lg, logging.INFO)

