from pydantic import RootModel
from copy import copy

def test_probe():
    class R(RootModel[list[int]]):
        pass
    m = R.model_construct()
    try:
        c = m.__copy__()
    except KeyError:
        c = 'keyerror'
    assert c != 'keyerror'

def test_bare():
    m = RootModel[int](1)
    c = m.__copy__()
    assert c == m
    assert copy(m) == m

