from fastapi import Depends
from fastapi.dependencies.utils import get_flat_dependant, get_dependant


def dep_a(q: int = 0):
    return q


def dep_b(a: int = Depends(dep_a), h: str = "x"):
    return a


def dep_c(a: int = Depends(dep_a), b: int = Depends(dep_b)):
    return a


def endpoint(c: int = Depends(dep_c), a: int = Depends(dep_a)):
    return c


def test_flat():
    d = get_dependant(path='/', call=endpoint)
    flat = get_flat_dependant(d)
    assert sorted(p.name for p in flat.query_params) == ['h', 'q', 'q', 'q']
    flat2 = get_flat_dependant(d, skip_repeats=True)
    assert sorted(p.name for p in flat2.query_params) == ['h', 'q']

