from pydantic.functional_validators import InstanceOf as IO


def test_probe():
    @dataclass
    class C1:
        a: 'Unknown' = 1  # noqa: F821

    @dataclass
    class C2:
        b: NotRequired[int] = 1

    class M(BaseModel):
        x: InstanceOf[C1]
        y: InstanceOf[C2]

    M(x=C1(), y=C2())
    with pytest.raises(ValidationError):
        M(x=1, y=1)

